const Event = z.discriminatedUnion("type", [
  z.object({ type: z.literal("order-created"),   id: z.string(), total: z.number() }),
  z.object({ type: z.literal("order-cancelled"), id: z.string(), reason: z.string() }),
]);
type Event = z.infer<typeof Event>;

function decode(text: string): Event {
  return Event.parse(JSON.parse(text));   // the tag selects the member schema
}
